I will read the cached Actual and Expected tables, group each stock’s contiguous rows using the R DAYS marker, and map Actual blocks to the Expected order. Then I will write the mapped plain values into A3:F37, replacing the helper formulas with their resulting values, and save the workbook. Diagnostics will be printed for debugging.

```python
import shutil
import openpyxl
from copy import copy

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)
ws = wb["Q"]
vws = vals["Q"]

def clean(v):
    if v is None:
        return None
    if isinstance(v, str):
        s = v.strip()
        return s if s else None
    return v

def nonblank(v):
    return v is not None and str(v).strip() != ""

FIRST = 3
LAST = 37
COLS = range(1, 7)

# Preserve original styles for the data region if possible.
style_map = {}
try:
    for r in range(FIRST, LAST + 1):
        for c in COLS:
            style_map[(r, c)] = copy(ws.cell(row=r, column=c)._style)
except Exception:
    style_map = {}

# Read actual values.
actual_values = {}
for r in range(FIRST, LAST + 1):
    row_vals = [clean(vws.cell(row=r, column=c).value) for c in COLS]
    e = vws.cell(row=r, column=5).value
    a = clean(vws.cell(row=r, column=1).value)
    # Column F is the helper formula: IF(NOT(ISBLANK(E)), A, "")
    row_vals[5] = a if nonblank(e) else None
    actual_values[r] = row_vals

# Group actual blocks by the row where R DAYS / helper symbol appears.
actual_blocks = []
start = FIRST
for r in range(FIRST, LAST + 1):
    e = vws.cell(row=r, column=5).value
    f = vws.cell(row=r, column=6).value
    if nonblank(e) or nonblank(f):
        sym = clean(f) or clean(vws.cell(row=start, column=1).value)
        rows = list(range(start, r + 1))
        actual_blocks.append({
            "symbol": sym,
            "rows": rows,
            "values": [actual_values[x] for x in rows]
        })
        start = r + 1

if start <= LAST:
    sym = clean(vws.cell(row=start, column=1).value)
    rows = list(range(start, LAST + 1))
    actual_blocks.append({
        "symbol": sym,
        "rows": rows,
        "values": [actual_values[x] for x in rows]
    })

# Fallback: fixed 5-row blocks.
if not actual_blocks:
    for start in range(FIRST, LAST + 1, 5):
        rows = list(range(start, min(start + 5, LAST + 1)))
        sym = clean(vws.cell(row=start, column=1).value)
        actual_blocks.append({
            "symbol": sym,
            "rows": rows,
            "values": [actual_values[x] for x in rows]
        })

# Locate expected table start column.
max_col = vws.max_column
exp_start = None
for c in range(1, max_col + 1):
    v = vws.cell(row=1, column=c).value
    if isinstance(v, str) and v.strip().lower() == "expected result":
        exp_start = c
        break

if exp_start is None:
    exp_start = 10
if exp_start > max_col:
    exp_start = max(1, max_col)

# Expected R DAYS is the 5th column of the expected table.
exp_rdays_col = exp_start + 4
if exp_rdays_col > max_col:
    exp_rdays_col = None

# Group expected blocks.
exp_blocks = []
start = FIRST

if exp_rdays_col is not None:
    for r in range(FIRST, LAST + 1):
        v = vws.cell(row=r, column=exp_rdays_col).value
        if nonblank(v):
            sym = clean(vws.cell(row=r, column=exp_start).value)
            rows = list(range(start, r + 1))
            exp_blocks.append({"symbol": sym, "rows": rows})
            start = r + 1

    if start <= LAST:
        sym = clean(vws.cell(row=start, column=exp_start).value)
        exp_blocks.append({"symbol": sym, "rows": list(range(start, LAST + 1))})
else:
    prev = None
    for r in range(FIRST, LAST + 1):
        sym = clean(vws.cell(row=r, column=exp_start).value)
        if sym != prev:
            if prev is not None:
                exp_blocks.append({"symbol": prev, "rows": list(range(start, r))})
            start = r
            prev = sym
    if prev is not None:
        exp_blocks.append({"symbol": prev, "rows": list(range(start, LAST + 1))})

# Fallback: fixed 5-row blocks.
if not exp_blocks:
    for start in range(FIRST, LAST + 1, 5):
        rows = list(range(start, min(start + 5, LAST + 1)))
        sym = clean(vws.cell(row=start, column=exp_start).value)
        exp_blocks.append({"symbol": sym, "rows": rows})

actual_lookup = {}
for b in actual_blocks:
    actual_lookup.setdefault(b["symbol"], []).append(b)

# Write actual blocks into expected order.
for eb in exp_blocks:
    sym = eb["symbol"]
    src = None

    if sym in actual_lookup and actual_lookup[sym]:
        src = actual_lookup[sym].pop(0)
    else:
        for k in list(actual_lookup.keys()):
            if k is not None and sym is not None and str(k).lower() == str(sym).lower():
                if actual_lookup[k]:
                    src = actual_lookup[k].pop(0)
                    break

    if src is None:
        print("Missing actual block for", sym)
        continue

    n = min(len(src["rows"]), len(eb["rows"]))
    if len(src["rows"]) != len(eb["rows"]):
        print("Length mismatch for", sym, len(src["rows"]), len(eb["rows"]))

    for i in range(n):
        src_r = src["rows"][i]
        dest_r = eb["rows"][i]
        for c in COLS:
            cell = ws.cell(row=dest_r, column=c)
            cell.value = src["values"][i][c - 1]
            if style_map:
                try:
                    cell._style = copy(style_map[(src_r, c)])
                except Exception:
                    pass

wb.save(OUT)

print("actual blocks:", [b["symbol"] for b in actual_blocks])
print("expected blocks:", [b["symbol"] for b in exp_blocks])
print("first data rows:", [[ws.cell(row=r, column=c).value for c in COLS] for r in range(FIRST, FIRST + 5)])
